                    for name, body in sorted(ent["tar"].items()):
                        data = body.encode("utf-8")
                        ti = tarfile.TarInfo(name)
                        ti.size, ti.mtime, ti.mode = len(data), 0, 0o644
                        tf.addfile(ti, io.BytesIO(data))
