  return n
}
function quote(s) { if (s ~ /[",]/ || s ~ /^ / || s ~ / $/) { gsub(/"/, "\"\"", s); return "\"" s "\"" } return s }
function cents(s,   neg, p, w, fr) {
  neg = 0
  if (substr(s, 1, 1) == "-") { neg = 1; s = substr(s, 2) } else if (substr(s, 1, 1) == "+") s = substr(s, 2)
  p = index(s, ".")
