  fr = substr(fr "00", 1, 2)
  return neg ? -((w + 0) * 100 + (fr + 0)) : (w + 0) * 100 + (fr + 0)
}
function money(c,   sign) { sign = ""; if (c < 0) { sign = "-"; c = -c } return sprintf("%s%d.%02d", sign, int(c / 100), c % 100) }

